import { index, jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

export const usageMetering = pgTable(
  "usage_metering",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    ownerId: text("owner_id"),
    organizationId: text("organization_id"),
    key: text("key").notNull(),
    title: text("title").notNull(),
    status: text("status").notNull().default("active"),
    metadata: jsonb("metadata").$type<Record<string, unknown>>().notNull().default({}),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
  },
  (item) => [
    index("usage_metering_owner_idx").on(item.ownerId),
    index("usage_metering_organization_idx").on(item.organizationId),
  ]
);

import "server-only";

export type UsageEventInput = {
  organizationId: string;
  key: string;
  quantity: number;
  occurredAt?: Date;
  metadata?: Record<string, unknown>;
};

export type UsageEvent = {
  organizationId: string;
  key: string;
  quantity: number;
  occurredAt: Date;
  metadata: Record<string, unknown>;
};

export function createUsageEvent(input: UsageEventInput): UsageEvent {
  if (!input.organizationId) throw new Error("organizationId is required.");
  if (!input.key) throw new Error("Usage key is required.");
  if (!Number.isFinite(input.quantity) || input.quantity <= 0) {
    throw new Error("Usage quantity must be a positive number.");
  }

  return {
    organizationId: input.organizationId,
    key: input.key,
    quantity: input.quantity,
    occurredAt: input.occurredAt ?? new Date(),
    metadata: input.metadata ?? {},
  };
}

export function aggregateUsage(events: UsageEvent[]) {
  return events.reduce<Record<string, number>>((totals, event) => {
    totals[event.key] = (totals[event.key] ?? 0) + event.quantity;
    return totals;
  }, {});
}

export const usageMeteringChecklist = [
  "Write events with tenant scope and an idempotency key",
  "Aggregate usage outside the request path when volume is high",
  "Reconcile metered totals with billing before invoicing",
] as const;

const metrics = [
  { key: "api_requests", quantity: "842,500", window: "Current billing period" },
  { key: "api_errors", quantity: "1,204", window: "Current billing period" },
  { key: "webhook_deliveries", quantity: "38,910", window: "Current billing period" },
];

export default function UsageMeteringPage() {
  return (
    <main className="flex flex-col gap-6 p-6">
      <div>
        <h1 className="text-2xl font-semibold">Usage</h1>
        <p className="text-muted-foreground">Usage event capture, aggregation helpers, and billing-ready usage UI.</p>
      </div>
      <div className="grid gap-3 md:grid-cols-3">
        {metrics.map((metric) => (
          <section key={metric.key} className="rounded-lg border p-4">
            <h2 className="font-mono text-xs text-muted-foreground">{metric.key}</h2>
            <p className="mt-2 text-2xl font-semibold">{metric.quantity}</p>
            <p className="text-sm text-muted-foreground">{metric.window}</p>
          </section>
        ))}
      </div>
    </main>
  );
}
